import React from 'react';

export default function TaskList({ tasks, onEdit, onDelete, auth }){
  return (
    <div>
      <h4>Tasks ({tasks.length})</h4>
      {tasks.map(t => (
        <div key={t._id} style={{ border: '1px solid #eee', padding: 8, marginBottom: 8 }}>
          <div style={{ display: 'flex', justifyContent: 'space-between' }}>
            <strong>{t.title}</strong>
            <small>{t.progress} {t.dueDate ? `| due ${new Date(t.dueDate).toLocaleDateString()}` : ''}</small>
          </div>
          <div>{t.description}</div>
          <div style={{ marginTop: 6 }}>
            {auth && auth.id === t.userId && (
              <>
                <button onClick={()=>onEdit(t)}>Edit</button>
                <button onClick={()=>onDelete(t._id)}>Delete</button>
              </>
            )}
          </div>
        </div>
      ))}
    </div>
  );
}
